// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockOffset) public {
        // bound blockOffset so that after the call, block.timestamp can be set
        vm.assume(blockOffset < 1000);
        // warp to some future time
        vm.warp(block.timestamp + blockOffset + 1);
        // record timestamp before fallback
        uint256 timeBefore = block.timestamp;
        // call fallback with exactly 10 ether
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");
        // require that the call succeeded
        assertTrue(success, "call should succeed");
        // read pastBlockTime after call
        uint256 storedTime = c.pastBlockTime();
        // The rule: after fallback, pastBlockTime should equal the block timestamp at the time of the call
        assertTrue(storedTime == timeBefore, "pastBlockTime should be updated to block.timestamp");
    }
}

